python3 << 'EOF'
with open('/opt/inventoryd/bin/inventoryd') as f:
    lines = f.readlines()

# Print the start() function
in_start = False
for i, line in enumerate(lines, 1):
    if 'def start():' in line:
        in_start = True
    if in_start:
        print(f"{i}: {line.rstrip()}")
        if line.strip() and not line[0].isspace() and i > 71:
            break
EOF
